'use strict';
const M=NasDemo,$=id=>document.getElementById(id),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=['Tổng quan','Lưu trữ','File Station','Danh tính','Phân quyền','Kết nối & Firewall','Nhật ký'];let page=pages[0];const events=[];
$('nav').innerHTML=pages.map((p,i)=>`<button data-page="${i}"><span class="nav-icon">${['◫','▤','▱','♙','◇','⊞','◷'][i]}</span>${p}</button>`).join('');M.devices.forEach(d=>{const o=document.createElement('option');o.value=d.id;o.textContent=d.name;$('device').append(o);});
$('nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b){page=pages[+b.dataset.page];render();}};$('device').onchange=render;$('close').onclick=()=>$('dialog').close();
function table(headers,rows){return `<div class="scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`;}
function card(label,value,note){return `<div class="card"><small>${label}</small><div class="number">${value}</div><span class="muted">${note}</span></div>`;}
function panel(title,body){return `<div class="panel"><h2>${title}</h2>${body}</div>`;}
function preview(kind,value,d){try{const text=M.preview(kind,value);$('detail').textContent=d.name+' · '+(kind==='acl'?'/SITE/CT-001 · ':'')+text;events.unshift([new Date().toLocaleTimeString('vi-VN'),kind,d.name,value]);$('dialog').showModal();$('error').textContent='';}catch(e){$('error').textContent=e.message;}}
function spark(color,values){const points=values.map((v,i)=>`${i*10},${80-v}`).join(' ');return `<svg viewBox="0 0 120 85" aria-hidden="true"><polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round"/></svg>`;}
function overview(list){const t=M.totals(list),pct=t.total?Math.round(t.used/t.total*100):0;return `<div class="section-heading"><div><h2>Toàn cảnh hạ tầng</h2><p class="muted">Sức khỏe thiết bị, tài nguyên và lưu trữ trong một màn hình.</p></div><span class="live-dot">BỘ DỮ LIỆU DEMO</span></div><div class="cards">${card('NAS TRỰC TUYẾN',list.filter(d=>d.online).length+'<span class="denominator"> / '+list.length+'</span>','● Trạng thái kết nối minh họa')}${card('DUNG LƯỢNG VOLUME',t.total+' <em>TiB</em>',t.missing+' NAS thiếu dữ liệu')}${card('VOLUME ĐÃ SỬ DỤNG',t.used.toFixed(1)+' <em>TiB</em>',pct+'% dung lượng đã biết')}${card('CẦN CHÚ Ý',list.filter(d=>!d.online||(d.used/d.total>.85)).length,'Mất kết nối hoặc Volume >85%')}</div><div class="dashboard-grid"><div class="panel traffic"><div class="section-heading"><div><h2>Lưu lượng mạng</h2><span class="muted">Dữ liệu xu hướng giả lập · không thu thập trực tiếp</span></div><div class="segmented"><button class="active" data-range="1h">1 giờ</button><button data-range="24h">24 giờ</button></div></div><div class="chart-legend"><span class="legend teal">Nhận</span><span class="legend blue">Gửi</span><b id="chart-period">1 giờ gần nhất · giả lập</b></div><svg class="network-chart" viewBox="0 0 700 220" role="img" aria-label="Biểu đồ lưu lượng mạng giả lập, trục dọc MB/s"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#0e998b" stop-opacity=".23"/><stop offset="1" stop-color="#0e998b" stop-opacity="0"/></linearGradient></defs>${[35,85,135,185].map((y,i)=>`<line x1="40" y1="${y}" x2="690" y2="${y}" stroke="#e9eef2" stroke-dasharray="4 4"/><text x="2" y="${y+4}" fill="#8695a7" font-size="10">${60-i*20}</text>`).join('')}<text x="0" y="12" fill="#8695a7" font-size="10">MB/s</text><path id="network-area" d="M40 150 L80 135 L120 145 L160 95 L200 110 L240 65 L280 85 L320 80 L360 110 L400 90 L440 40 L480 68 L520 56 L560 90 L600 70 L645 35 L690 55 L690 185 L40 185Z" fill="url(#fill)"/><path id="network-in" d="M40 150 L80 135 L120 145 L160 95 L200 110 L240 65 L280 85 L320 80 L360 110 L400 90 L440 40 L480 68 L520 56 L560 90 L600 70 L645 35 L690 55" fill="none" stroke="#159b8e" stroke-width="3" stroke-linejoin="round"/><path id="network-out" d="M40 170 L80 160 L120 165 L160 150 L200 165 L240 125 L280 145 L320 135 L360 155 L400 140 L440 115 L480 130 L520 105 L560 135 L600 120 L645 95 L690 115" fill="none" stroke="#6d8bdd" stroke-width="2.5" stroke-linejoin="round"/>${['09:00','09:15','09:30','09:45','10:00'].map((v,i)=>`<text data-chart-tick="${i}" x="${40+i*155}" y="211" fill="#8695a7" font-size="11">${v}</text>`).join('')}</svg></div><div class="panel capacity"><h2>Phân bổ dung lượng</h2><div class="donut" style="--used:${pct}%"><div><strong>${pct}<small>%</small></strong><span>đã sử dụng</span></div></div><div class="capacity-row"><span class="legend teal">Đã dùng</span><b>${t.used.toFixed(1)} TiB</b></div><div class="capacity-row"><span class="legend gray">Còn trống</span><b>${(t.total-t.used).toFixed(1)} TiB</b></div><p class="muted">Chỉ tính Volume có dữ liệu. ${t.missing} NAS chưa có số liệu.</p></div></div><div class="section-heading"><div><h2>Thiết bị trong hệ thống <span class="count">${list.length}</span></h2><p class="muted">Chọn thiết bị để khám phá lưu trữ vật lý và logic.</p></div></div><div class="device-grid">${list.map(d=>`<button class="device-tile ${d.online?'':'disconnected'}" data-storage="${d.id}"><div class="tile-top"><span class="device-symbol">▤</span><span class="status ${d.online?'':'off'}">● ${d.online?'Trực tuyến':'Mất kết nối'}</span></div><h3>${d.name}</h3><p class="muted">${d.model} · ${d.site}</p><div class="device-metrics"><div><small>CPU</small><strong>${d.online?d.cpu+'%':'—'}</strong>${spark('#159b8e',d.online?[18,24,20,30,25,40,22,35,28,30,20,18,22]:[])}</div><div><small>RAM</small><strong>${d.online?d.ram+'%':'—'}</strong>${spark('#7186d9',d.online?[30,34,32,35,33,38,40,38,42,44,40,42,42]:[])}</div></div><div class="capacity-row"><span>Volume</span><b>${d.online?d.used+' / '+d.total+' TiB':'Chưa có dữ liệu'}</b></div><div class="meter"><i class="${d.used/d.total>.85?'amber':''}" style="width:${d.online?d.used/d.total*100:0}%"></i></div><div class="tile-bottom">${!d.online?'Kiểm tra kết nối':d.used/d.total>.85?'◉ Dung lượng vượt 85%':'◉ Xem chi tiết lưu trữ'}<span>↗</span></div></button>`).join('')}</div><div class="insight"><span>◇</span><div><b>Quản trị tập trung, triển khai từng bước</b><p>Giám sát → Danh tính → Phân quyền → Firewall. Tích hợp Zabbix / Prometheus ở giai đoạn tiếp theo.</p></div><span class="badge">Bản thiết kế</span></div>`;}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',pages[+b.dataset.page]===page));$('title').textContent=page;const selected=$('device').value,list=selected==='all'?M.devices:M.devices.filter(d=>d.id===selected),d=M.devices.find(d=>d.id===selected)||M.devices[0];$('scope').textContent=selected==='all'?'Chi tiết mặc định: NAS-SITE-DEMO':d.site+' · DSM 7.x giả lập';let h='';
if(page==='Tổng quan'){h=overview(list);}
else if(page==='Nhật ký'){h=panel('Nhật ký prototype',`<p class="muted">Ghi việc xem trước trong bộ nhớ; chưa phải audit production. Không lọc theo NAS ở màn hình này.</p>`+(events.length?table(['Thời gian','Loại','NAS','Giá trị','Kết quả'],events.map(e=>[...e.map(esc),'Chỉ xem trước'])):'<p class="empty">Chưa có hoạt động. Thử xem trước ACL hoặc IP.</p>'));}
else if(!d.online){h=panel(d.name,'<p class="empty">NAS mất kết nối. Không có dữ liệu khả dụng; không suy ra trạng thái khỏe hoặc danh sách rỗng.</p>');}
else if(page==='Lưu trữ'){h=`<div class="cards">${card('Ổ vật lý','48 TiB','12 × 4 TiB · minh họa')}${card('Pool khả dụng',d.total+' TiB','Số liệu giả sau RAID')}${card('Volume đã dùng',d.used+' TiB','Volume 1 · Btrfs')}${card('Sức khỏe','Cần xem','1 ổ cảnh báo giả lập')}</div>`+panel(d.name+' · Sơ đồ khay minh họa',`<p class="muted">Sơ đồ chung 12 khay, không phải cấu hình model thật.</p><div class="bays">${Array.from({length:12},(_,i)=>`<button class="bay ${i===3?'warn':''}" data-bay="${i+1}"><span class="disk-led"></span><span class="disk-number">${String(i+1).padStart(2,'0')}</span><span class="disk-vents">≡<br>≡<br>≡</span><b>HDD</b><span>4 TiB</span><small>${i===3?'Cảnh báo':'Bình thường'}</small></button>`).join('')}</div><p id="disk-detail">Chọn khay để xem chi tiết giả lập.</p>`)+`<br>`+panel('Lưu trữ logic',table(['Lớp','Đối tượng','Quan hệ','Trạng thái'],[['Pool','Storage Pool 1','RAID 6 · khay 1–12','Kiểm tra khay 4'],['Volume','Volume 1 · Btrfs','Storage Pool 1',`${d.used} / ${d.total} TiB`],['SSD Cache','—','—','Chưa có dữ liệu'],['LUN / Target','—','—','Chưa có dữ liệu']]));}
else if(page==='File Station'){h=`<div class="grid">${panel('Thư mục',`<div class="tree">▾ SITE<br>　<button data-folder="CT-001">CT-001</button><br>　<button data-folder="CT-002">CT-002</button></div><p class="muted">Chỉ metadata giả; không mở tài liệu.</p>`)}${panel(d.name,`<h3 id="path"></h3><div id="files"></div>`)}</div>`;}
else if(page==='Danh tính'){h=panel('User & Group',`<p class="muted">Danh tính toàn ứng dụng, không khẳng định tài khoản có trên NAS đã chọn. Không tự hợp nhất tên trùng.</p><div class="filters"><input id="search" aria-label="Tìm tài khoản" placeholder="Tìm tài khoản"><select id="source" aria-label="Nguồn danh tính"><option value="">Tất cả nguồn</option><option>Thủ công</option><option>LDAP</option><option>Portal Office</option></select></div><div id="users"></div><p class="muted">Đồng bộ một chiều → đối chiếu định danh → xem trước → duyệt. Chưa kết nối nguồn thật.</p>`);}
else if(page==='Phân quyền'){h=panel('Xem trước ACL · '+d.name,`<p>Thư mục giả lập: <b>/SITE/CT-001</b></p><p class="muted">Chưa tính quyền hiệu lực từ quyền share, ACL và nhóm.</p>${table(['Đối tượng','Nguồn quyền','Quyền hiện tại'],[['KYTHUAT','Trực tiếp · Allow','Đọc'],['IT','Kế thừa · Allow','Đọc / Ghi']])}<p><label>Quyền mới cho KYTHUAT <select id="permission"><option>Đọc</option><option>Đọc / Ghi</option></select></label></p><p>Chỉ thư mục này; không áp đệ quy.</p><button id="acl-preview">Xem trước thay đổi giả lập</button><p id="error" class="error" role="alert"></p>`);}
else {h=`<div class="grid">${panel('Kết nối · '+d.name,table(['User','IP / giao thức'],[['demo.user','192.0.2.18 · SMB']])+'<p class="muted">IP thuộc dải tài liệu. Chưa kiểm chứng API ngắt phiên.</p><button disabled>Ngắt phiên · chưa hỗ trợ trong mẫu</button>')}${panel('Đề xuất chặn IP',`<label>IPv4 <input id="ip" value="192.0.2.18" aria-label="IP cần chặn"></label><p class="muted">Chưa đọc luật thật hoặc xác minh đường khôi phục.</p><button id="ip-preview">Xem trước</button> <button disabled>Thực thi bị khóa</button><p id="error" class="error" role="alert"></p>`)}</div>`;}
$('content').innerHTML=h;document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));$('chart-period').textContent=(b.dataset.range==='1h'?'1 giờ':'24 giờ')+' gần nhất · giả lập';document.querySelectorAll('[data-chart-tick]').forEach((tick,i)=>{tick.textContent=(b.dataset.range==='24h'?['Hôm qua','16:00','22:00','04:00','10:00']:['09:00','09:15','09:30','09:45','10:00'])[i];});const shift=b.dataset.range==='24h'?'translate(0 10)':'translate(0 0)';['network-in','network-out','network-area'].forEach(id=>$(id).setAttribute('transform',shift));});document.querySelectorAll('[data-storage]').forEach(b=>b.onclick=()=>{$('device').value=b.dataset.storage;page='Lưu trữ';render();});document.querySelectorAll('[data-bay]').forEach(b=>b.onclick=()=>{$('disk-detail').textContent=`Khay ${b.dataset.bay} · HDD 4 TiB · Serial DEMO-${b.dataset.bay} · 36°C · S.M.A.R.T.: ${b.dataset.bay==='4'?'cảnh báo':'bình thường'} (giả lập). Không chạy kiểm tra thật.`;});
if($('users')){const update=()=>{const u=M.filterUsers($('search').value,$('source').value);$('users').innerHTML=u.length?table(['Tài khoản','Nguồn','Nhóm'],u.map(u=>[esc(u.name),esc(u.source),esc(u.group)])):'<p class="empty">Không có kết quả phù hợp.</p>';};$('search').oninput=update;$('source').onchange=update;update();}
if($('files')){const folder=name=>{$('path').textContent='/SITE/'+name;$('files').innerHTML=table(['Tên','Loại','Dung lượng'],[[esc(name+'-ban-ve.pdf'),'PDF · metadata','12 MiB'],['Hồ sơ nghiệm thu','Thư mục','Chưa tính']]);};document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>folder(b.dataset.folder));folder('CT-001');}if($('acl-preview'))$('acl-preview').onclick=()=>preview('acl',$('permission').value,d);if($('ip-preview'))$('ip-preview').onclick=()=>preview('ip',$('ip').value,d);
}render();
